# Check signs and relative directions more carefully

demos = [
    ("D1", ((3,11),(10,1)), [(4,8), (5,7), (6,6), (7,5), (8,4), (9,3)]),
    ("D2", ((1,1),(13,8)), [(2,2), (3,2), (4,2), (5,2), (6,2), (7,2), (8,3), (9,4), (10,5), (11,6), (12,7)]),
    ("D3", ((1,6),(12,3)), [(2,5), (3,5), (4,5), (5,5), (6,5), (7,5), (8,5), (9,5), (10,5), (11,4)]),
    ("D4", ((13,2),(1,11)), [(2,11), (3,10), (4,9), (5,8), (6,7), (7,6), (8,5), (9,5), (10,5), (11,5), (12,5)])]

for name, (p2, p1), outputs in demos:
    print(f"{name}:")

    dr = p1[0] - p2[0]
    dc = p1[1] - p2[1]

    # Sign of movements  
    if dr > 0:
        dr_sign = "+"
    elif dr < 0:
        dr_sign = "-"
    else:
        dr_sign = "="

    if dc > 0:
        dc_sign = "+"
    elif dc < 0:
        dc_sign = "-"
    else:
        dc_sign = "="

    print(f"  Δr: {dr:+3} ({dr_sign}), Δc: {dc:+3} ({dc_sign})")

    # Direction classification
    if dr_sign == "+" and dc_sign == "+":
        dir_class = "down-right"
    elif dr_sign == "+" and dc_sign == "-":
        dir_class = "down-left"
    elif dr_sign == "-" and dc_sign == "+":
        dir_class = "up-right"
    elif dr_sign == "-" and dc_sign == "-":
        dir_class = "up-left"
    else:
        dir_class = "same row/col"

    print(f"  Direction class: {dir_class}")

    # Now look at first output position
    first_pt = outputs[0]
    print(f"  First output: {first_pt}, from p2 delta: ({first_pt[0]-p2[0]}, {first_pt[1]-p2[1]})")
    print()

